/**
 * Applies versioned, forward-only migrations from ./migrations (generated by `pnpm db:generate`).
 * Usage: DATABASE_URL=mysql://… pnpm db:migrate            (or DATABASE_URL_FILE=/path/to/secret)
 * The URL is read from the environment/secret file only — never from argv (process lists are public).
 *
 * Diagnostics are fixed categories. Driver and ORM messages can contain statements, parameters or
 * connection details, so they are never printed — not even at debug level.
 * Exit codes: 0 up to date · 1 failed/unknown · 75 lock busy · 78 configuration.
 */
import path from "node:path";
import { readFileSync } from "node:fs";
import mysql from "mysql2/promise";
import { drizzle } from "drizzle-orm/mysql2";
import { migrate } from "drizzle-orm/mysql2/migrator";
import { connectionOptionsFromUrl, DatabaseUrlError } from "../../server/db/connectionOptions.js";

type Stage = "configuration" | "connect" | "lock" | "apply" | "verify";

function driverCode(error: unknown): string {
  const code = (error as { code?: unknown } | null)?.code;
  return typeof code === "string" && /^[A-Z0-9_]{1,64}$/.test(code) ? code : "UNKNOWN";
}

async function main(): Promise<number> {
  let stage: Stage = "configuration";
  let connection: mysql.Connection | undefined;
  let locked = false;
  try {
    const url = process.env.DATABASE_URL_FILE ? readFileSync(process.env.DATABASE_URL_FILE, "utf8").trim() : process.env.DATABASE_URL;
    if (!url) {
      console.error("Configuration error: DATABASE_URL (or DATABASE_URL_FILE) must be set.");
      return 78;
    }
    const options = connectionOptionsFromUrl(url);
    const migrationsFolder = process.env.RP_MIGRATIONS_DIR ?? path.resolve(import.meta.dirname, "../../migrations");

    stage = "connect";
    connection = await mysql.createConnection(options);

    stage = "lock";
    const [rows] = await connection.query("SELECT GET_LOCK('rp_schema_migration', 30) AS acquired");
    if ((rows as { acquired: number }[])[0]?.acquired !== 1) {
      console.error("Another migration is in progress (could not acquire the migration lock). Nothing was changed.");
      return 75;
    }
    locked = true;

    stage = "apply";
    await migrate(drizzle(connection), { migrationsFolder });

    stage = "verify";
    const [applied] = await connection.query("SELECT COUNT(*) AS n FROM `__drizzle_migrations`");
    console.log(`Migrations are up to date (${(applied as { n: number }[])[0]?.n ?? 0} applied).`);
    return 0;
  } catch (error) {
    if (error instanceof DatabaseUrlError) {
      console.error(`Configuration error: ${error.message}`);
      return 78;
    }
    const outcome =
      stage === "configuration"
        ? "The database secret or migrations folder could not be read. Nothing was changed."
        : stage === "connect" || stage === "lock"
          ? "Nothing was changed."
          : stage === "apply"
            ? "OUTCOME UNKNOWN: a migration may be partially applied (MySQL DDL is not transactional). Inspect __drizzle_migrations and the schema before retrying; do not start the application."
            : "Migrations ran but the result could not be confirmed. Inspect __drizzle_migrations before starting the application.";
    console.error(`Migration failed at stage '${stage}' (driver code ${driverCode(error)}). ${outcome}`);
    return 1;
  } finally {
    if (connection) {
      if (locked) await connection.query("SELECT RELEASE_LOCK('rp_schema_migration')").catch(() => undefined);
      await connection.end().catch(() => undefined);
    }
  }
}

main().then(
  (code) => {
    process.exitCode = code;
  },
  () => {
    console.error("Migration failed unexpectedly. Outcome unknown.");
    process.exitCode = 1;
  },
);
